/**
 * shadcn-vue Override Boot File
 *
 * CSS-only mode: adds body.body--shadcn class so the CSS theme
 * (shadcn-theme.scss) can style native Quasar components.
 *
 * No compat wrappers are registered — Quasar's own components render
 * natively and the CSS theme handles all visual overrides.
 */
import { boot } from 'quasar/wrappers';
import { safeBoot } from 'src/utils/bootSafety';

// Empty overrides map — kept for backward compatibility with imports
const COMPAT_OVERRIDES: Record<string, never> = {};

export { COMPAT_OVERRIDES };

export default boot(safeBoot('shadcn-overrides', () => {
  // Add body class so CSS theme (shadcn-theme.scss) activates
  document.body.classList.add('body--shadcn');

  console.info('[shadcn] CSS-only theme active');
}));
